profiles={}
def add(key,archetype,under,perf,variation,cases):
 profiles[key]={'archetype':archetype,'expectations':[{'id':'understanding-performance','essentialUnderstandingDe':under[0],'essentialUnderstandingEn':under[1],'observablePerformanceDe':perf[0],'observablePerformanceEn':perf[1]}],'coverageExpectations':{'requiredExpectationIds':['understanding-performance'],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':'meaningful-changed-condition','textDe':variation[0],'textEn':variation[1]}],'applicationCaseBriefs':[{'id':f'fresh-case-{i+1}','taskDemandDe':c[0],'taskDemandEn':c[1],'expectedPerformanceDe':c[2],'expectedPerformanceEn':c[3],'understandingFocusDe':c[4],'understandingFocusEn':c[5]}for i,c in enumerate(cases)]}
add('question-hypothesis','experiment',('Eine Hypothese verknüpft eine gezielt veränderbare Bedingung mit einem beobachtbaren Ergebnis; Beobachtungen müssen die Vermutung auch in Frage stellen können.','A hypothesis links a condition that can be changed deliberately to an observable outcome; observations must also be capable of challenging it.'),('Die lernende Person grenzt eine Frage zu Stoffeigenschaften oder Stoffveränderungen ab, formuliert eine begründete Vorhersage und nennt ein mögliches entgegenstehendes Ergebnis.','The learner frames a question about material properties or changes, states a justified prediction, and names a possible conflicting result.'),('Variation zwischen Rühren und Temperatur als möglichem Einfluss auf das Lösen; fachliche Erklärung wird als Annahme gegeben.','Vary stirring and temperature as possible influences on dissolution; relevant chemical explanations are supplied as assumptions.'),[
('Kochsalz löst sich in Wasser. Formuliere eine untersuchbare Frage zum Einfluss des Rührens und eine begründete Hypothese. Welche Beobachtung würde die Vorhersage in Frage stellen?','Table salt dissolves in water. Formulate an investigable question about stirring and a justified hypothesis. What observation would challenge the prediction?','Die lernende Person macht Rühren zur Einflussgröße, Lösezeit zur beobachtbaren Ergebnisgröße und hält Salz-/Wassermenge sowie Temperatur vergleichbar. Sie benennt eine nicht verkürzte Lösezeit als mögliches Gegenresultat.','The learner identifies stirring as the factor and dissolution time as the observed outcome, keeping amounts and temperature comparable. They name an unchanged or longer time as a possible counter-result.','Prüfbarkeit statt bloßer Behauptung.','Testability rather than an unsupported assertion.'),
('Neue Situation: Ohne Rühren wird Salz in Wasser unterschiedlicher Temperatur gegeben. Formuliere eine neue Frage/Hypothese; alle benötigten Angaben zur Stoffeigenschaft werden bereitgestellt.','Fresh situation: salt is added without stirring to water at different temperatures. Formulate a new question and hypothesis; required material-property information is provided.','Die lernende Person unterscheidet die neue Einflussgröße von Rühren, sagt ein beobachtbares Ergebnis voraus und beschreibt, welche Gegenbeobachtung zur Überprüfung führen würde.','The learner distinguishes the new factor from stirring, predicts an observable result, and states which contrary observation would prompt reconsideration.','Übertragen der Frage-Hypothese-Beziehung auf eine andere Bedingung.','Transfer the question-hypothesis relation to a different condition.')])
add('investigation','experiment',('Eine Untersuchung prüft den behaupteten Einfluss nur, wenn Vergleichsbedingungen nachvollziehbar sind und Beobachtungen vom Deuten getrennt dokumentiert werden.','An investigation tests a proposed influence only when comparison conditions are clear and observations are recorded separately from interpretation.'),('Die lernende Person legt eine veränderte Bedingung und vergleichbare übrige Bedingungen fest, führt die freigegebene Untersuchung unter Anleitung aus und protokolliert Ablauf, Beobachtungen und begrenzte Schlussfolgerung.','The learner defines the changed factor and comparable remaining conditions, carries out the approved investigation under guidance, and documents procedure, observations, and a bounded conclusion.'),('Rühren und Korngröße verändern den Vergleich sachlich; Durchführung und Protokoll müssen zur jeweiligen Frage passen.','Stirring and grain size change the comparison meaningfully; procedure and record must match each question.'),[
('Prüfe unter Lehrkraftanleitung mit freigegebenen Materialien, ob Rühren die Lösezeit gleicher Kochsalzportionen verändert. Plane den Vergleich, führe ihn tatsächlich durch und protokolliere ihn.','Under teacher guidance using approved materials, investigate whether stirring changes the dissolution time of equal portions of table salt. Plan the comparison, perform it, and record it.','Die lernende Person verwendet gleiche Wasser-/Salzmengen und Temperatur, verändert nur Rühren, beobachtet ein zuvor festgelegtes Lösekriterium und notiert Ergebnisse ohne ein vorweggenommenes Resultat.','The learner uses equal amounts and temperatures, changes stirring only, observes a predefined dissolution criterion, and records results without assuming an outcome.','Tatsächliche angeleitete Durchführung mit kontrolliertem Vergleich.','Actual guided performance with a controlled comparison.'),
('Neuer freigegebener Versuch unter Anleitung: Vergleiche gleich große Massen groben und feinen Kochsalzes bei gleichem Rühren. Lege vorab fest, wie Du Zeiten und Beobachtungen protokollierst.','Fresh approved guided investigation: compare equal masses of coarse and fine table salt with the same stirring. Decide beforehand how to record times and observations.','Die lernende Person passt die Einflussgröße an, hält übrige Bedingungen vergleichbar, führt den Versuch aus und trennt dokumentierte Beobachtung, mögliche Fehler und Aussage zur Hypothese.','The learner changes the factor appropriately, maintains comparable conditions, performs the investigation, and separates recorded observation, possible error, and conclusions about the hypothesis.','Neue Frage verlangt neue Kontrollbedingungen; keine vorgegebene Versuchsschrittfolge als eigene Spezialkompetenz.','A new question requires different controls; no prescribed specialist procedure is introduced as a competence.')])
add('data-documentation','data',('Daten sind erst nachvollziehbar, wenn erkennbar ist, was unter welchen Bedingungen in welcher Einheit gemessen oder beobachtet wurde.','Data can be understood only when the measured or observed quantity, conditions, and units are identifiable.'),('Die lernende Person ordnet Rohnotizen zu einer nachvollziehbaren Tabelle oder einem Protokoll und kennzeichnet fehlende Angaben als offen.','The learner organizes raw notes into a clear table or record and marks missing information as unresolved.'),('Zeitmesswerte und qualitative Farb-/Zustandsbeobachtungen brauchen unterschiedliche Dokumentation.','Time measurements and qualitative observations of color or state require different documentation.'),[
('Bereitgestellte Unterrichtsnotizen zur Salzlösung nennen Wasser bei 20 °C, je 2 g Salz und Lösezeiten 65 s, 70 s und 67 s. Dokumentiere Versuch und Messwerte.','Supplied classroom notes on salt dissolution list water at 20 °C, 2 g of salt per trial, and times of 65 s, 70 s, and 67 s. Document the investigation and results.','Die lernende Person gibt Messgröße, Einheit, gleiche Bedingungen und getrennte Wiederholungen an, ohne zusätzliche nicht gemessene Größen zu ergänzen.','The learner records quantity, unit, common conditions, and separate repetitions without inventing additional measurements.','Rohdaten bleiben rückverfolgbar.','Raw data remain traceable.'),
('Neue Notizen berichten qualitative Beobachtungen verschiedener Indikatorproben mit Probenkennungen und Zeitpunkten. Erstelle ein verständliches Protokoll; die Indikatorerklärung wird mitgeliefert.','Fresh notes report qualitative observations of different indicator samples with sample identifiers and times. Create a clear record; the indicator explanation is supplied.','Die lernende Person erhält Probenkennungen und beobachtete Farben, unterscheidet Beobachtung von chemischer Einordnung und macht fehlende Versuchsbedingungen sichtbar.','The learner preserves sample identifiers and observed colors, distinguishes observations from chemical classification, and identifies missing experimental conditions.','Eine qualitative Beobachtung ist kein erfundener Zahlenmesswert.','A qualitative observation is not an invented numerical measurement.')])
add('data-interpretation','data',('Ein Muster in chemischen Daten stützt eine begrenzte Aussage; Streuung und geänderte Versuchsbedingungen beeinflussen ihre Aussagekraft.','A pattern in chemical data supports a bounded claim; variation and changed conditions affect its strength.'),('Die lernende Person wählt eine zum Datentyp passende Darstellung, beschreibt das Muster, berücksichtigt mögliche Fehler und vergleicht das Ergebnis begründet mit der Hypothese.','The learner chooses a representation suited to the data, describes the pattern, considers possible errors, and compares the result with the hypothesis using reasons.'),('Wiederholungen unter gleichen Bedingungen gegenüber einem Vergleich mit verändertem Wasser-/Salzverhältnis.','Repeated trials under the same conditions versus a comparison with changed water-to-salt ratios.'),[
('Unterrichtsdaten: gleiche Salz-/Wassermengen und Temperatur, ohne Rühren 110/115/112 s, mit Rühren 60/64/62 s. Stelle sie dar und beurteile die Hypothese Rühren verkürzt die Lösezeit.','Classroom data: equal amounts and temperature, no stirring 110/115/112 s, stirring 60/64/62 s. Represent them and assess the hypothesis that stirring shortens dissolution time.','Die lernende Person beschreibt den Unterschied und die Streuung, stützt die Hypothese für diese Bedingungen und nennt Zeitmessung oder uneinheitliches Rühren als mögliche Fehler.','The learner describes the difference and spread, supports the hypothesis for these conditions, and names timing or inconsistent stirring as possible errors.','Muster, Streuung und begrenzte Folgerung hängen zusammen.','Pattern, variability, and a bounded inference are linked.'),
('Neue bereitgestellte Daten zeigen längere Lösezeiten bei größeren Salzportionen; gleichzeitig wurden verschiedene Wassermengen genutzt. Was lässt sich daraus zur Wirkung der Salzmenge schließen?','Fresh supplied data show longer times for larger salt portions, but different water volumes were also used. What can be concluded about the effect of salt amount?','Die lernende Person erkennt die gemeinsam veränderten Bedingungen, erklärt die eingeschränkte Vergleichbarkeit und schlägt einen kontrollierten neuen Vergleich statt einer sicheren Kausalbehauptung vor.','The learner recognizes jointly changed conditions, explains limited comparability, and proposes a controlled comparison instead of a certain causal claim.','Geänderter Fall trennt Korrelation und überprüfbaren Einfluss.','A changed case separates association from a testable influence.')])
add('inquiry-limits','concept',('Eine Untersuchung beantwortet nur Fragen, die ihr Vergleich und ihre Beobachtungen tatsächlich erfassen; offenbleibende Fragen können weitere Untersuchungen benötigen.','An investigation answers only questions addressed by its comparison and observations; unresolved questions may need further investigation.'),('Die lernende Person benennt beantwortete und offene Fragen und erklärt den Unterschied anhand konkreter Beobachtungen und Bedingungen.','The learner identifies answered and unresolved questions and explains the distinction using concrete observations and conditions.'),('Gleiche Beobachtung erlaubt eine Aussage zum untersuchten Verlauf, aber nicht automatisch zu allen Stoffen oder persönlichen Vorlieben.','The same observation supports a claim about the investigated process, but not automatically about all substances or personal preferences.'),[
('Ein gegebener Rührversuch zeigt kürzere Kochsalz-Lösezeiten bei gleicher Menge und Temperatur. Welche Frage beantwortet er? Kann er belegen, dass Rühren alle Stoffe gleich beeinflusst?','A supplied stirring experiment shows shorter table-salt dissolution times at equal amount and temperature. Which question does it answer? Does it show the same effect for all substances?','Die lernende Person begrenzt die Aussage auf die untersuchten Bedingungen und nennt die Übertragung auf andere Stoffe als offene Frage.','The learner bounds the result to the tested conditions and identifies transfer to other substances as unresolved.','Reichweite einer konkreten Untersuchung.','Scope of a concrete investigation.'),
('Eine gegebene Untersuchung vergleicht die Trübung zweier Wasserproben. Welche naturwissenschaftliche Frage kann sie beantworten und warum beantwortet sie nicht, welche Probe schöner ist?','A supplied investigation compares cloudiness in two water samples. Which scientific question can it answer, and why does it not determine which sample is prettier?','Die lernende Person trennt beobachtbar prüfbare Eigenschaften von einer Wert- oder Vorliebenfrage und nennt benötigte zusätzliche Daten für weitergehende chemische Aussagen.','The learner distinguishes testable properties from a question of value or preference and identifies additional data needed for broader chemical claims.','Naturwissenschaftliche Prüfbarkeit und andere Fragen unterscheiden.','Distinguish scientific testability from other kinds of question.')])
add('validity-criteria','concept',('Chemische Ergebnisse gewinnen Aussagekraft durch prüfbare Hypothesen, nachvollziehbare und wiederholbare Bedingungen, unabhängige Nachprüfung und konsistente Deutung; jede Schlussfolgerung bleibt auf ihre Datenbasis begrenzt.','Chemical findings gain strength through testable hypotheses, clear repeatable conditions, independent checking, and consistent interpretation; every conclusion remains limited by its evidence.'),('Die lernende Person beurteilt einen Untersuchungsbericht mit den fünf gebundenen Kriterien, begründet Kritik konkret und unterscheidet einen verlässlichen Gegenbefund von einem Durchführungsfehler.','The learner assesses an investigation report using the five bound criteria, gives specific reasons, and distinguishes a reliable conflicting result from a procedural error.'),('Zuverlässiger Gegenbefund versus fehlende Kontrolle oder uneinheitliche Beobachtung; Ergebnisse aus einem zweiten Labor.','A reliable conflicting result versus missing controls or inconsistent observation; results from another laboratory.'),[
('Ein bereitgestellter Bericht behauptet aus einer einzigen unkontrollierten Lösezeit, ein Zusatzstoff beschleunige das Lösen immer. Prüfe Reproduzierbarkeit, Falsifizierbarkeit, Intersubjektivität, Konsistenz und Vorläufigkeit.','A supplied report claims from one uncontrolled dissolution time that an additive always speeds dissolution. Assess reproducibility, falsifiability, intersubjectivity, consistency, and provisionality.','Die lernende Person benennt fehlende Vergleichs-/Wiederholungsbedingungen, fordert eine prüfbare Vorhersage und trennt die Aussagekraft der Daten von einem absoluten Geltungsanspruch.','The learner identifies missing controls and repetitions, demands a testable prediction, and separates the evidence strength from an absolute claim.','Kriterien begründen konkrete Kritik.','Criteria support specific criticism.'),
('Ein zweites Labor erhält unter dokumentierten vergleichbaren Bedingungen wiederholt ein entgegenstehendes Ergebnis; in einem anderen Versuch war das Messgerät defekt. Beurteile beide Befunde.','A second laboratory repeatedly obtains a conflicting result under documented comparable conditions; in another trial the measuring instrument failed. Assess both findings.','Die lernende Person unterscheidet den ernst zu prüfenden Gegenbefund vom ungeeigneten fehlerhaften Versuch und erklärt, weshalb Nachprüfung die vorläufige Theorie verändern kann.','The learner distinguishes the credible conflicting evidence from an invalid faulty trial and explains why checking can change a provisional theory.','Widerlegung verlangt passende Bedingungen und belastbare Beobachtung.','Falsification requires appropriate conditions and reliable observations.')])
add('source-appraisal','data',('Die Eignung einer chemischen Quelle hängt von ihrer konkreten Aussage, überprüfbaren Grundlage, Urheberschaft, Absicht und Passung zur Frage ab.','The suitability of a chemistry source depends on its specific claim, verifiable basis, authorship, purpose, and relevance to the question.'),('Die lernende Person prüft angebotene Quellen anhand nachvollziehbarer Merkmale und begründet, welche Aussage sie für eine chemische Frage verwenden kann.','The learner checks offered sources using clear features and explains which claims can be used for a chemistry question.'),('Offizielle Umweltinformation, Produktwerbung und unbestätigte Behauptung im Beitrag verlangen unterschiedliche Begründung.','Official environmental information, product advertising, and an unsupported post require different justification.'),[
('Vergleiche den tatsächlichen UBA-Artikel Reinigung im Haushalt mit einer als Übung erfundenen Werbeaussage Ein Reiniger ist immer völlig umweltfreundlich. Welche Angaben eignen sich für eine sachliche Frage nach Umwelteinträgen?','Compare the actual UBA article on household cleaning with a clearly fictional advertising claim that a cleaner is always completely environmentally friendly. Which information is suitable for a factual question about environmental releases?','Die lernende Person identifiziert UBA als Urheber, Umweltinformation als Zweck und die begrenzten Sachangaben zu Inhaltsstoffen/Abwasser. Sie begründet Kritik am unbelegten pauschalen Werbeversprechen statt nur einem Behördenlogo zu folgen.','The learner identifies the UBA authorship, environmental-information purpose, and bounded statements about ingredients and wastewater. They justify criticism of the unsupported advertising claim rather than relying only on a government logo.','Quellenwahl folgt Belegen und Fragebezug.','Source selection follows evidence and relevance.'),
('Nutze den tatsächlichen UBA-Artikel Wäsche waschen und Waschmittel für eine neue Frage zur Dosierung. Eine als Übung erfundene Social-Media-Notiz nennt keinen Autor und empfiehlt doppelte Menge. Prüfe die Aussagen.','Use the actual UBA article on washing clothes and detergents for a fresh question about dosage. A clearly fictional social-media note has no author and recommends double the amount. Assess the claims.','Die lernende Person prüft Urheber, Begründung und Bezug zur angegebenen Dosierung, erkennt die fehlende Grundlage der Notiz und beschreibt, welche Angaben aus der Quelle für die Frage relevant sind.','The learner checks authorship, justification, and relevance to the stated dosage, recognizes the unsupported note, and identifies which source information answers the question.','Übertragung auf eine andere Inhaltsaussage.','Transfer to a different factual claim.')])
add('information-presentation','representation',('Eine sachgerechte Darstellung erhält den Zusammenhang zwischen chemischer Aussage, begrenzendem Kontext und zugehöriger Quelle und passt Erklärung und Form an die Zielgruppe an.','An appropriate representation preserves links between a chemical claim, its limiting context, and its source, while adapting explanation and form to the audience.'),('Die lernende Person wählt relevante bereitgestellte Informationen aus, strukturiert sie verständlich und benennt die Quellen so, dass Aussagen nachvollziehbar sind.','The learner selects relevant supplied information, structures it clearly, and identifies sources so that claims can be checked.'),('Kurze Erklärung für Mitschüler versus sachliche Übersicht für eine schulische Entscheidung.','A short explanation for classmates versus a factual summary for a school decision.'),[
('Erstelle aus dem tatsächlichen UBA-Artikel zur Haushaltsreinigung eine kurze sachliche Erklärung für Mitschüler zum Zusammenhang von Dosierung und Stoffeintrag ins Abwasser; gib die Quelle an.','Use the actual UBA household-cleaning article to create a short factual explanation for classmates about dosage and chemical releases into wastewater; identify the source.','Die lernende Person ordnet die relevante Aussage, erklärt den Zusammenhang verständlich, erhält den Anwendungsrahmen und kennzeichnet die Quelle mit Titel, Urheber und Link.','The learner organizes the relevant claim, explains the relationship clearly, preserves its context, and identifies the source by title, authoring organization, and link.','Darstellung macht den fachlichen Zusammenhang zugänglich.','Representation makes the chemical relationship accessible.'),
('Neue Aufgabe: Nutze den UBA-Waschmittelartikel und eine ausdrücklich fiktive Unterrichtstabelle mit Dosierung/Kosten für eine Übersicht für eine schulische Gruppe; trenne Quelleninformation und eigene Darstellung.','Fresh task: use the UBA detergent article and an explicitly fictional classroom table of dosage and costs to prepare a summary for a school group; distinguish source information from your representation.','Die lernende Person wählt passende Form und Informationen, verbindet Zahlen mit korrekten Einheiten, erhält Bedingungen und führt tatsächliche Quelle und Unterrichtsdaten getrennt auf.','The learner chooses an appropriate form and information, uses correct units, preserves conditions, and identifies the actual source separately from classroom data.','Adressatenwechsel verändert die Aufbereitung, nicht die fachliche Aussage.','Changing the audience changes presentation rather than the factual claim.')])
add('argument-appraisal','concept',('Ein Argument wird durch seinen fachlichen Bezug und das verwendete Bewertungskriterium tragfähig; Nutzen und Nachteile können verschiedene Kriterien betreffen.','An argument is supported by its chemical relevance and evaluation criterion; benefits and drawbacks may concern different criteria.'),('Die lernende Person ordnet vorgegebene Pro-/Kontra-Argumente den Kriterien zu, beurteilt ihre fachliche Grundlage und formuliert ein begründetes Abwägen.','The learner assigns given arguments to criteria, assesses their scientific basis, and states a reasoned balance.'),('Gleiche chemische Sachinformation bei veränderter Zielsetzung oder Gewichtung der vorgegebenen Kriterien.','The same chemical information under a changed purpose or weighting of given criteria.'),[
('Für eine schulische Reinigungsentscheidung liegen bereitgestellte Aussagen aus dem UBA-Artikel und fiktive Preisangaben vor. Wäge Argumente anhand der vorgegebenen Kriterien Wirksamkeit, Umweltbelastung und Kosten ab.','For a school-cleaning decision, supplied claims from the UBA article and fictional prices are provided. Weigh arguments using the given criteria of effectiveness, environmental burden, and cost.','Die lernende Person verbindet Argumente mit passenden Kriterien, unterscheidet chemisch begründete Angaben von Preisurteilen und macht Zielkonflikte nachvollziehbar.','The learner links arguments to appropriate criteria, distinguishes scientific information from price judgments, and explains trade-offs.','Kriterium und fachlicher Beleg tragen das Argument.','Criterion and scientific evidence support the argument.'),
('Neue Situation: Für denselben Produktvergleich gilt als Ziel geringerer Chemikalieneintrag bei gleicher notwendiger Reinigung. Prüfe, welche zuvor gegebenen Argumente nun stärker oder schwächer tragen.','Fresh situation: for the same product comparison, the aim is lower chemical release with the same necessary cleaning. Assess which earlier arguments become stronger or weaker.','Die lernende Person begründet eine veränderte Abwägung mit dem geänderten Ziel und erhält zutreffende fachliche Angaben, statt aus einem anderen Urteil andere Stoffeigenschaften abzuleiten.','The learner justifies a changed balance using the changed aim and preserves accurate material information rather than inferring new properties from a different judgment.','Wertungsänderung und Tatsachenänderung unterscheiden.','Distinguish a change in judgment from a change in facts.')])
add('integrated-career-keep','concept',('Chemische Tätigkeiten verbinden die Untersuchung oder Veränderung von Stoffen mit konkreten gesellschaftlichen Anwendungen; Berufsfelder haben dabei unterschiedliche Aufgaben.','Chemical work links investigation or transformation of materials to societal applications; career fields perform different tasks.'),('Die lernende Person erklärt an einem gegebenen Anwendungsfall die chemische Aufgabe, die gesellschaftliche Bedeutung und die dazugehörigen beruflichen Tätigkeiten im Zusammenhang.','The learner explains the chemical task, societal significance, and related career activities together in a supplied application case.'),('Produktentwicklung und Umweltüberwachung tragen verschiedene Aufgaben bei und verlangen unterschiedliche Informationen.','Product development and environmental monitoring contribute different tasks and require different information.'),[
('Ein bereitgestellter Unterrichtsfall beschreibt Waschmittelentwicklung, Prüfung der Zusammensetzung und Überwachung von Stoffeinträgen in Gewässer. Ordne chemische Aufgaben und Berufstätigkeiten zu und erkläre die Bedeutung für den Alltag.','A supplied classroom case describes detergent development, composition testing, and monitoring releases to water. Relate chemical tasks to career activities and explain their everyday significance.','Die lernende Person verbindet Entwickeln/Analysieren mit Stoffeigenschaften und Umwelteinträgen, unterscheidet passende Arbeitsfelder und begründet deren Beitrag statt Berufe nur aufzuzählen.','The learner relates development and analysis to material properties and releases, distinguishes relevant work fields, and explains their contribution rather than listing occupations.','Ein Anwendungskontext verbindet Chemie, gesellschaftliche Bedeutung und Berufe.','One application context links chemistry, societal significance, and careers.'),
('Neue bereitgestellte Fallkarte: Trinkwasser wird auf Inhaltsstoffe geprüft; technische Aufbereitung und Qualitätskontrolle sind getrennte Aufgaben. Erläutere, weshalb chemische Kenntnisse in beiden Arbeitsfeldern gebraucht werden.','Fresh supplied case card: drinking water is tested for constituents; technical treatment and quality control are separate tasks. Explain why chemical knowledge is needed in both fields.','Die lernende Person ordnet die auf der Fallkarte genannten chemischen Tätigkeiten nachvollziehbar ein und erklärt Bedeutung und Aufgabenunterschied ohne unbelegte allgemeine Nutzen-Risiko-Pfeile.','The learner explains the chemical activities supplied on the card, their significance, and differences in tasks without unsupported general benefit-risk arrows.','Übertragen auf ein anderes Berufsfeld mit konkreter chemischer Arbeit.','Transfer to another career field involving concrete chemical work.')])
add('decision-evaluation','concept',('Eine chemische Entscheidung verbindet nachvollziehbare fachliche Chancen und Risiken mit ethischen, ökologischen, ökonomischen und sicherheitsbezogenen Kriterien; die begrenzte Datenbasis und Zielkonflikte beeinflussen das Urteil.','A chemistry-related decision combines supported benefits and risks with ethical, environmental, economic, and safety criteria; limited evidence and trade-offs affect the judgment.'),('Die lernende Person begründet die vier Kriterienfamilien am Fall, wägt Handlungsoptionen ab und überprüft eine begründete Entscheidung bei veränderter Information oder Zielsetzung.','The learner justifies the four families of criteria in a case, weighs action options, and reviews a justified decision when information or aims change.'),('Produktmenge, Betroffenengruppen, Kosten und verfügbare Sachinformation verändern Optionen und Urteil.','Product amount, affected groups, costs, and available evidence change options and judgments.'),[
('Ein gegebenes schulisches Fallpaket enthält UBA-Reinigungsinformationen, fiktive Produktmengen/Kosten und Angaben zu betroffenen Personen. Begründe Kriterien für eine Reinigungsentscheidung und prüfe zwei vorgegebene Optionen.','A supplied school case packet includes UBA cleaning information, fictional quantities and costs, and information about affected people. Justify criteria for a cleaning decision and assess two given options.','Die lernende Person verknüpft fachliche Wirksamkeit/Umwelteinträge und sichere Anwendung mit Kosten und fairer Berücksichtigung Betroffener, wägt Optionen ab und begründet ihre Entscheidung samt Informationsgrenzen.','The learner connects effectiveness, releases, and safe use with costs and fair consideration of affected people, weighs options, and justifies the decision and information limits.','Vier Kriterienfamilien werden fachlich im Fall begründet.','The four criteria families are justified within the chemical case.'),
('Für einen neuen Waschmittel-Fall werden Dosierhinweise aus dem UBA-Artikel, fiktive Kosten und ein geändertes Nutzungsszenario bereitgestellt. Prüfe, ob eine zunächst gewählte Option beibehalten werden kann.','For a fresh detergent case, UBA dosage information, fictional costs, and a changed usage scenario are supplied. Assess whether an initial option can be retained.','Die lernende Person prüft Chancen und Risiken erneut, benennt veränderte Kriteriengewichte oder Sachbedingungen und revidiert oder bestätigt das Urteil mit Gründen.','The learner reassesses benefits and risks, identifies changed criterion weights or conditions, and revises or confirms the decision with reasons.','Neue Bedingungen machen Entscheidungsüberprüfung sichtbar.','Changed conditions reveal reasoned decision review.')])
add('knowledge-influences','concept',('Naturwissenschaftliches Wissen entsteht unter gesellschaftlichen und technischen Bedingungen; deren Einfluss auf Forschungsfragen, verfügbare Verfahren oder Verbreitung ist von fachlicher Begründung eines Ergebnisses zu unterscheiden.','Scientific knowledge develops under societal and technical conditions; their influence on questions, available methods, or dissemination is distinct from the scientific justification of a finding.'),('Die lernende Person ordnet konkrete dokumentierte Bedingungen einem chemischen Wissensentwicklungsfall zu und beurteilt deren Einfluss mit Quellenbezug und offengelegter Unsicherheit.','The learner relates documented conditions to a case of chemical knowledge development and assesses their influence with source references and stated uncertainty.'),('Technische Möglichkeiten und ökologische gesellschaftliche Anliegen beeinflussen Forschung unterschiedlich.','Technical capabilities and environmental societal concerns influence research in different ways.'),[
('Für die Entwicklung eines chemischen Untersuchungsmodells liegt ein noch bereitzustellendes, quellengeprüftes Oberstufen-Fallpaket mit Zeitlinie, Forschungsfragen und technischen Bedingungen vor. Beurteile, welche Bedingungen Fragen und Verfahren beeinflussten.','A source-verified upper-secondary case packet, still to be supplied, contains a timeline, research questions, and technical conditions for the development of a chemical investigation model. Assess which conditions influenced questions and methods.','Die lernende Person belegt Einflüsse mit konkreten Dokumentangaben und unterscheidet einen nachgewiesenen Zusammenhang von einer nur plausiblen Deutung.','The learner supports influences with specific documents and distinguishes an evidenced relationship from a plausible interpretation.','Quellengebundene Einflüsse statt pauschaler Geschichtserzählung.','Source-bound influences rather than a general historical narrative.'),
('Ein zweites noch bereitzustellendes, quellengeprüftes Fallpaket verbindet eine Umweltfrage mit chemischer Forschung und gesellschaftlicher Diskussion. Vergleiche Einflüsse mit dem ersten Fall; alle sachlichen Chemiedetails werden gegeben.','A second source-verified packet, still to be supplied, links an environmental question to chemistry research and societal debate. Compare influences with the first case; all factual chemical details are provided.','Die lernende Person prüft soziale/kulturelle, technische/historische, ökologische/ökonomische Bedingungen dort, wo Dokumente sie belegen, kennzeichnet Lücken und begründet Unterschiede.','The learner examines social/cultural, technical/historical, and environmental/economic conditions where documented, marks gaps, and justifies differences.','Einfluss auf Wissensentwicklung bleibt von Folgen einer Anwendung getrennt.','Influence on knowledge development remains distinct from the consequences of an application.')])
add('societal-impacts','concept',('Die Wirkung eines chemischen Produkts oder Verfahrens auf Gesellschaft und Umwelt hängt von Verwendung, Stoffströmen und Randbedingungen ab; nachhaltige Entwicklung verlangt begründetes Abwägen.','A chemical product or process affects society and the environment according to its use, material flows, and conditions; sustainable development requires reasoned evaluation.'),('Die lernende Person verbindet dokumentierte chemische Stoffeinträge mit gesellschaftlichen Wirkungen, bewertet sie anhand nachvollziehbarer Kriterien und nennt die Grenzen ihres Urteils.','The learner links documented chemical releases with societal impacts, assesses them using clear criteria, and states the limits of the judgment.'),('Veränderte Nutzung und Stoffmenge verändern Wirkungen; Entwicklung von Wissen und Anwendungsfolgen sind verschiedene Gegenstände.','Changed use and amount change impacts; knowledge development and application consequences are distinct subjects.'),[
('Nutze die tatsächlichen UBA-Angaben zu Haushaltsreinigung und bereitgestellte fiktive Mengenangaben, um gesellschaftliche und ökologische Folgen einer Reinigungsoption zu bewerten.','Use the actual UBA household-cleaning information and supplied fictional amounts to assess societal and environmental impacts of a cleaning option.','Die lernende Person verbindet Nutzen im gegebenen Gebrauch mit Stoffeinträgen, berücksichtigt betroffene Gruppen und begründet ein begrenztes nachhaltigkeitsbezogenes Urteil.','The learner links benefits in the supplied use case to releases, considers affected groups, and justifies a bounded sustainability judgment.','Anwendungsfolgen werden fachlich und kriterienbezogen bewertet.','Application impacts are assessed using chemistry and explicit criteria.'),
('Neuer Fall: Waschmittel werden nach vorgegebenen Dosierhinweisen oder in doppelter fiktiver Menge verwendet. Vergleiche die gesellschaftlichen und ökologischen Folgen mit dem UBA-Waschmittelartikel.','Fresh case: detergents are used at supplied label doses or double fictional amounts. Compare societal and environmental impacts using the UBA detergent article.','Die lernende Person begründet Unterschiede mit den bereitgestellten Stoffmengen und Quelleninformationen, macht begrenzte Annahmen kenntlich und setzt mehr Produkt nicht pauschal mit besserem Ergebnis gleich.','The learner explains differences using supplied quantities and source information, states limited assumptions, and does not equate more product with a better outcome.','Geänderte Stoffströme statt eines identischen Wertungsbeispiels.','Changed material flows rather than an identical evaluation case.')])
add('discussion-keep','concept',('Eine fachliche Diskussion verbindet chemische Erklärung und überprüfbare Argumente mit konstruktiver Prüfung fremder Einwände; der eigene Standpunkt kann durch bessere fachliche Gründe verändert werden.','A scientific discussion combines chemical explanation and checkable arguments with constructive consideration of objections; stronger scientific reasons can change one’s standpoint.'),('Die lernende Person erklärt einen gegebenen chemischen Sachverhalt schlüssig, vertritt einen begründeten Standpunkt, greift den fachlichen Einwand eines Gegenübers auf und bestätigt oder korrigiert ihre Aussage mit Gründen.','The learner explains a supplied chemical issue coherently, states a justified standpoint, addresses a scientific objection from another person, and confirms or corrects the claim with reasons.'),('Ein verändertes Datum oder eine andere Systemgrenze kann einen Einwand fachlich relevant machen.','Changed data or a different system boundary can make an objection scientifically relevant.'),[
('Bereitgestellte Messwerte zeigen: Beim Lösen einer bestimmten Salzprobe kühlt das Wasser ab. Erkläre den gegebenen Sachverhalt und diskutiere den fachlichen Einwand, dass die Messung auch von der Umgebung beeinflusst wird; notwendige Energiedaten werden bereitgestellt.','Supplied measurements show water cooling when a particular salt sample dissolves. Explain the supplied situation and discuss the scientific objection that surroundings can affect the measurement; necessary energy information is provided.','Die lernende Person erklärt mit den gegebenen Energiedaten, unterscheidet System und Umgebung, reagiert auf den Einwand sachlich und begrenzt oder korrigiert die Aussage anhand des Protokolls.','The learner explains using supplied energy information, distinguishes system and surroundings, responds constructively, and bounds or corrects the claim using the record.','Fachliche Argumentation und Austausch sind beide beobachtbar.','Both scientific reasoning and exchange are observable.'),
('Neue Diskussion mit vorgegebenen Konzentrationsdaten: Zwei chemische Lösungen erscheinen unterschiedlich wirksam, wurden aber in verschiedenen Mengen eingesetzt. Ein Gegenüber kritisiert den Vergleich. Erkläre und prüfe den Einwand.','Fresh discussion with supplied concentration data: two chemical solutions seem differently effective but were used in different amounts. Another person challenges the comparison. Explain and assess the objection.','Die lernende Person begründet die eingeschränkte Vergleichbarkeit fachlich, würdigt den Einwand und revidiert oder präzisiert den eigenen Standpunkt mit einer überprüfbaren Vergleichsbedingung.','The learner scientifically explains limited comparability, considers the objection, and revises or refines their standpoint with a checkable comparison condition.','Neuer fachlicher Gegenstand verlangt begründete Standpunktreflexion.','A new scientific subject requires reasoned reflection on one’s standpoint.')])
add('model-comparison','modeling',('Ein chemisches Modell hebt bestimmte Eigenschaften hervor und lässt andere weg; seine Eignung hängt von der Fragestellung und nicht von bloßer Ähnlichkeit ab.','A chemistry model highlights some properties and omits others; suitability depends on the question rather than mere resemblance.'),('Die lernende Person nutzt und vergleicht gegebene Modelle zu einer chemischen Frage, erklärt die jeweils dargestellten Informationen und nennt eine konkrete Grenze.','The learner uses and compares supplied models for a chemistry question, explains the information each represents, and names a specific limitation.'),('Materieaufbau und Reaktionsverlauf verlangen verschiedene Modellinformationen.','Matter structure and reaction progress require different model information.'),[
('Vergleiche bereitgestellte Kugel-Stab- und Kalottenmodelle eines Wassermoleküls für die Fragen Bindungsanordnung und räumlicher Platzbedarf; benötigte Fachangaben werden gegeben.','Compare supplied ball-and-stick and space-filling water models for questions about bond arrangement and spatial extent; required scientific information is supplied.','Die lernende Person erklärt, welches Modell welche Frage deutlicher zeigt, erkennt symbolische Größen und benennt, dass keine Darstellung ein maßstäbliches Foto oder die vollständige Moleküldynamik ist.','The learner explains which model better addresses each question, recognizes symbolic sizes, and notes that neither is a scale photograph or a full account of molecular dynamics.','Fragestellung begründet die Wahl.','The question justifies the choice.'),
('Eine neue bereitgestellte Teilchenanimation zeigt eine einfache Reaktion, ein statisches Bild nur Anfangs- und Endzustand. Vergleiche Aussagen über Teilchenanordnung und Ablauf; eine Reaktionsdeutung wird mitgeliefert.','A fresh supplied particle animation shows a simple reaction while a static image shows only initial and final states. Compare information about particle arrangement and progress; an explanation of the reaction is provided.','Die lernende Person nutzt beide Darstellungen, unterscheidet Zustands- und Ablaufinformation und benennt eine Grenze der schematischen Animation, etwa nicht reale Geschwindigkeiten.','The learner uses both representations, distinguishes state and process information, and identifies a limitation of the schematic animation, such as non-realistic speeds.','Übertragung vom Molekülbild auf ein anderes Modellziel.','Transfer from a molecule image to another modeling purpose.')])
add('advanced-model-comparison','modeling',('Modelle komplexer Moleküle unterscheiden Verknüpfung, Raumgestalt und Wechselwirkungen; ein plausibles räumliches Zusammenpassen allein belegt keine biochemische oder pharmazeutische Wirkung.','Models of complex molecules distinguish connectivity, spatial shape, and interactions; plausible spatial fit alone does not establish biochemical or pharmaceutical action.'),('Die lernende Person vergleicht bereitgestellte organische Molekül-/Wechselwirkungsmodelle, begründet ihre Eignung für die gegebene Frage und beschreibt Grenzen der Schlussfolgerung.','The learner compares supplied organic-molecule and interaction models, justifies their suitability for a given question, and describes limits of inference.'),('Verknüpfungsmodell gegenüber Raum-/Ladungsmodell; statische Geometrie gegenüber Simulation unter angegebenen Bedingungen.','Connectivity model versus spatial/charge model; static geometry versus simulation under stated conditions.'),[
('Gegeben sind Strukturformel und räumliches Modell eines organischen Moleküls in einem biochemischen Fall. Erkläre, welches Modell Verknüpfung und welches räumliche Wechselwirkungsmöglichkeiten zeigt; alle Stoff- und Funktionsangaben liegen vor.','A structural formula and a spatial model of an organic molecule are supplied in a biochemical case. Explain which depicts connectivity and which shows possible spatial interactions; all substance and function information is provided.','Die lernende Person begründet den Modellvergleich mit dargestellten Informationen, unterscheidet Modellschluss von empirischer Funktionsangabe und benennt fehlende dynamische oder Umgebungsinformation.','The learner justifies the comparison using represented information, distinguishes model inference from empirical function data, and identifies missing dynamic or environmental information.','Modellgrenzen statt eigenständigem Erlernen einer neuen biochemischen Methode.','Model limits rather than learning a new biochemical method as a separate competence.'),
('Neuer pharmazeutischer Fall: Ein statisches räumliches Modell und eine bereitgestellte Simulation zeigen verschiedene Umgebungsbedingungen einer molekularen Wechselwirkung. Vergleiche Aussagekraft und Grenzen; Wirkungsdaten werden gegeben.','Fresh pharmaceutical case: a static spatial model and a supplied simulation represent different environmental conditions of a molecular interaction. Compare explanatory power and limits; action data are provided.','Die lernende Person erläutert, welche Bedingung die Simulation berücksichtigt, prüft Annahmen und trennt mögliche Wechselwirkung von belegter Wirkung. Sie begründet, welche zusätzliche Modellinformation für die Frage nötig wäre.','The learner explains which condition the simulation represents, checks assumptions, and separates possible interaction from established action. They justify additional model information needed for the question.','Neue Randbedingungen verändern die Aussagekraft des Modells.','Changed conditions alter model explanatory power.')])
now=datetime.datetime.now(datetime.timezone.utc).isoformat().replace('+00:00','Z')
goals=[];candidate=[];index=[]
for row in d['goals']:
 original=next(g for g in canonical['goals'] if g['id']==row['goalId'])
 proposals=row['afterProposals'] or [{'proposalKey':'integrated-career-keep' if row['ordinal']==5 else 'discussion-keep','stage':'Sek I' if row['ordinal']==5 else 'Sek II','descriptionDe':original['description'],'descriptionEn':original['descriptionEn']}]
 for n,p in enumerate(proposals):
  key=p['proposalKey'];g=copy.deepcopy(original)
  g['id']=original['id'] if len(proposals)==1 else 'candidate:'+original['id']+':'+key
  g['description']=p['descriptionDe'];g['descriptionEn']=p['descriptionEn'];g['resourceLinks']=[]
  if len(proposals)>1:
   g['title']=key.replace('-',' ');g['titleEn']=key.replace('-',' ');g['shortKey']='candidate_'+original['shortKey']+'_'+key.replace('-','_')
  goals.append(g)
  reason=f"Nur Vorbereitungsprofil für {key}; keine gültige aktuelle D2-Auflösung oder Registrierung. {row['candidateDecision']}: {row['findingDe']}"
  candidate.append({'goalId':g['id'],'reason':reason,'evidenceLevel':'E1','maximumClaimScope':'G1','dissent':[row['remainingSourceCoverageObligation']],'profile':profiles[key]})
  index.append({'parentCurrentGoalId':row['goalId'],'candidateGoalId':g['id'],'proposalKey':key,'candidateStage':p['stage'],'currentGoalFingerprint':row['currentGoalFingerprint'],'proposedTextChanges':g['description']!=original['description'] or g['descriptionEn']!=original['descriptionEn'],'temporaryIdNotCanonical':g['id'].startswith('candidate:'),'imageBinding':'none in provisional profile; exact current asset binding retained in current-nine-inventory.json','readyForActiveRegistration':False,'requiresBeforeRegistration':['Resolve existing D2 dissent and semantic/stage/source split','Decide final IDs and prerequisite graph','Correct/rebind known image content where applicable','Build actual current goal page and targeted independent D/P review'], 'sourcePacketReady':key!='knowledge-influences'})
setobj={'schemaVersion':1,'authoringContract':'positive-understanding-evidence-candidates-v1','reviewId':'chemie-b008-targeted-continuation-candidate-c-v1','reviewedAt':now,'reviewer':'Codex independent continuation C; exact deployed model version not exposed','goals':candidate}
snapshot={'landscapeId':canonical['landscapeId'],'title':'B008 provisional review surface: proposed competencies; never active canonical','goals':goals}
for name,obj in [('positive-evidence.candidates.json',setobj),('provisional-profile-goals.json',snapshot),('profile-binding-index.json',{'schemaVersion':1,'DfreezeByteDigest':'sha256:'+hashlib.sha256((out/'D-findings.frozen.json').read_bytes()).hexdigest(),'authoredAfterDfreeze':now,'activeB008PositiveConfigFound':False,'profiles':index})]:
 (out/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
print('Authored',len(candidate),'positive V2 profile proposals for',len(d['goals']),'current goal families at',now)
